mapper.select:
SELECT GROUP_CONCAT(T10.COUNTER_NAME order by T10.COUNTER_NAME SEPARATOR ',') assetSupplyBank, T1.CCY, T1.PRIN_AMT, T1.TRADE_DATE, T3.VDATE vDate, t3.MDATE mDate, t3.TERM_DAYS, t5.YIELD*100 YIELD, t5.BASIS, t7.IS_GUARANTEE, t8.TYPE_6, t6.PORTFOLIO_NAME, t1.TRADE_ID bizCode, t14.BUSI_ACCT_NO payAcctNo, t14.ACCT_NAME payAcctName, t14.BANK_DEP payBankDept, t12.SETTLE_AMT, t13.BUSI_ACCT_NO receiveAcctNo, t13.ACCT_NAME receiveAcctName, t13.BANK_DEP, T15.PAY_CYCLE, t11.COUNTER_NAME FROM
WFL_TRD_PRODUCT_DEAL T1 LEFT JOIN WFL_TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN WFL_STL_PAY_ORDERS T12 ON T12.TRADE_ID = T1.TRADE_ID AND T12.IS_TOTAL_TRADE = #{NO}
TRD_PRODUCT_DEAL T1 LEFT JOIN TRD_PRODUCT_DEAL_ADD T2 ON T1.TRADE_ID = T2.TRADE_ID LEFT JOIN STL_PAY_ORDERS T12 ON T12.TRADE_ID = T1.TRADE_ID AND T12.IS_TOTAL_TRADE = #{NO}
LEFT JOIN FIN_PRODUCT T3 ON T1.FINPROD_ID = T3.FINPROD_ID LEFT JOIN FIN_CASH_INFO T4 ON T4.FINPROD_ID = T1.FINPROD_ID AND T4.FINPROD_TYPE = #{FIN_CASH_BUSINESS_TYPE_01} AND T4.CASH_TYPE_2 = #{CASH_TYPE_2_C02} LEFT JOIN FIN_CASH_CALC_RULE T5 ON T4.CASH_ID = T5.CASH_ID AND T5.EFF_DATE = T3.VDATE LEFT JOIN FIN_CASH_PAY_RULE T15 ON T4.CASH_ID = T15.CASH_ID AND T15.EFF_DATE = T3.VDATE LEFT JOIN PTL_PORTFOLIO T6 ON T6.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN PA_PTL_PORTFOLIO T7 ON T6.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN FIN_PRODUCT_TYPE T8 ON T3.FINPROD_ID = T8.FINPROD_ID LEFT JOIN PA_FIN_PRODUCT T9 ON T3.FINPROD_ID = T9.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY T10 ON concat_ws('', ',' , ifnull(T9.ASSET_PROVIDER) , ',') LIKE concat_ws('', '%,' , T10.COUNTER_ID , ',%') LEFT JOIN MST_COUNTER_PARTY T11 ON T1.COUNTER_ID = T11.COUNTER_ID LEFT JOIN STL_CAPACCT_INFO T13 ON (T13.ACCT_NO = T12.MY_ACCT_NO AND T12.PS = #{IE_FLAG_01}) OR (T13.ACCT_NO = T12.COUNTER_ACCT_NO AND T12.PS = #{IE_FLAG_02}) LEFT JOIN STL_CAPACCT_INFO T14 ON (T14.ACCT_NO = T12.MY_ACCT_NO AND T12.PS = #{IE_FLAG_02}) OR (T14.ACCT_NO = T12.COUNTER_ACCT_NO AND T12.PS = #{IE_FLAG_01})
WHERE (T1.TRADE_ID = #{bizCode} AND T1.TRADE_STATUS = #{TRADE_STATUS_01}) OR (T1.P_TRADE_ID = #{bizCode} AND T1.TRADE_STATUS = #{TRADE_STATUS_03})
where T1.TRADE_ID = #{bizCode}
group by T1.CCY, T1.PRIN_AMT, T1.TRADE_DATE, T3.VDATE, t3.MDATE, t3.TERM_DAYS, t5.YIELD, t5.BASIS, t7.IS_GUARANTEE, t8.TYPE_6, t6.PORTFOLIO_NAME, t1.TRADE_ID, t14.BUSI_ACCT_NO, t14.ACCT_NAME, t14.BANK_DEP, t12.SETTLE_AMT, t13.BUSI_ACCT_NO, t13.ACCT_NAME, t13.BANK_DEP, T15.PAY_CYCLE, t11.COUNTER_NAME
